add("regex-email", /\bregex\b.*\b(?:for |to (?:match|validate) )?(?:an )?email\b|\bvalidate (?:an )?email (?:address )?(?:with |using )?regex\b/i, "Email regex (practical)", "javascript", "const EMAIL = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\nEMAIL.test(\"a.b@example.com\"); // true", "A full RFC 5322 regex is huge and still not a deliverability check; validate the shape, then send a confirmation email.");
add("npm-update", /\b(?:update|upgrade)\b.*\b(?:npm )?(?:packages|dependencies|deps)\b.*\b(?:npm|node|package\.json)?|\bnpm (?:update|upgrade|outdated)\b/i, "Update npm dependencies", "bash", "npm outdated                         # what is behind\nnpm update                           # within the ranges in package.json\nnpx npm-check-updates -u && npm install   # bump the ranges themselves (majors too)", "");
add("npm-init-project", /\b(?:start|init|initialize|create|set ?up|bootstrap)\b.*\b(?:new )?(?:node|npm|javascript|js) project\b/i, "Start a Node project", "bash", "mkdir app && cd app\nnpm init -y\nnpm pkg set type=module\nnpm install express\necho 'node_modules\\n.env' > .gitignore\ngit init", "");
add("http-status-codes", /\b(?:list of |common )?http status codes\b|\bwhat (?:do|does) (?:the )?(?:http )?status codes? mean\b/i, "Common HTTP status codes", "text", "200 OK               201 Created          204 No Content\n301 Moved Permanently 302 Found            304 Not Modified\n400 Bad Request      401 Unauthorized     403 Forbidden\n404 Not Found        405 Method Not Allowed 409 Conflict\n422 Unprocessable    429 Too Many Requests\n500 Internal Error   502 Bad Gateway      503 Unavailable      504 Gateway Timeout", "401 means not authenticated (who are you?); 403 means authenticated but not allowed.");
add("json-vs-yaml", /\bjson (?:to|vs|versus|or) yaml\b|\byaml (?:to|vs|versus|or) json\b|\bconvert (?:json|yaml) (?:to|into) (?:yaml|json)\b/i, "JSON to YAML", "bash", "# yq (https://github.com/mikefarah/yq)\nyq -P '.' file.json > file.yaml        # JSON -> YAML\nyq -o=json '.' file.yaml > file.json   # YAML -> JSON\n# Python\npython3 -c 'import sys,json,yaml; print(yaml.safe_dump(json.load(sys.stdin)))' < file.json", "DI does not run converters on your document offline; these commands do it on your machine.");

