export const ENTRIES = H;
// words the typo corrector must leave alone ("div" is not "dig", "npm" is not "nap")
// every word an entry's pattern or title mentions is vocabulary too ("footer", "params", "ellipsis")
const PATTERN_WORDS = [...new Set(H.flatMap((h) => (h.re.source + " " + h.title).toLowerCase().match(/[a-z][a-z0-9]{2,}/g) || []))];
export const VOCAB = [...PATTERN_WORDS, "div", "css", "html", "js", "javascript", "node", "npm", "npx", "git", "commit", "commits", "stash", "branch", "rebase", "merge", "amend", "unstage", "untrack", "cherry", "squash", "tag", "tags", "clone", "diff", "remote", "push", "pull", "sql", "yaml", "yml", "json", "docker", "dockerfile", "compose", "container", "containers", "bash", "shell", "grep", "sed", "awk", "curl", "wget", "ssh", "scp", "rsync", "tar", "tgz", "zip", "unzip", "chmod", "chown", "cron", "crontab", "nohup", "tmux", "symlink", "venv", "pip", "argparse", "dataclass", "dataclasses", "fstring", "fstrings", "enumerate", "zip", "lambda", "regex", "fetch", "debounce", "throttle", "clipboard", "localstorage", "urlsearchparams", "promise", "promises", "async", "await", "upsert", "index", "join", "joins", "flask", "django", "fastapi", "express", "nginx", "postgres", "postgresql", "mysql", "sqlite", "redis", "mongodb", "kubernetes", "openssl", "cert", "certificate", "tls", "ssl", "bcrypt", "argon2", "dig", "nslookup", "traceroute", "mtr", "ping", "nmap", "netcat", "lsof", "df", "du", "env", "dotenv", "viewport", "flexbox", "grid", "ellipsis", "scrollbar", "svg", "api", "http", "https", "ip", "dns", "port", "url", "uuid", "sudo", "linux", "ubuntu", "mac", "macos", "windows", "vim", "nano", "python", "python3", "pip3", "pipenv", "poetry", "requirements"];
export function ask(input) {
  const s = String(input || "").trim().replace(/\s+/g, " ");
  if (s.length < 6 || s.length > 200) return null;
  // strip the question frame so "how do i undo the last git commit" and "undo last git commit" match alike
  const core = s.replace(/^(?:how (?:do|can|would|should) (?:i|you|we|one)|how to|what(?:'s| is) the (?:command|way|syntax) (?:to|for)|show me how to|i want to|i need to|help me)\s+/i, "").replace(/[?.!]+$/, "");
  const hits = H.filter((h) => h.re.test(core) || h.re.test(s));
  if (!hits.length) return null;
  return { id: hits[0].id, alt: hits.slice(1, 4).map((h) => h.id), query: s };
}
export function run(q) {
  if (!q) return { ok: false, error: "not a how-to I have" };
  const e = H.find((h) => h.id === q.id);
  return e ? { ok: true, id: e.id, title: e.title, lang: e.lang, code: e.code, body: e.body, note: e.note, alt: q.alt.map((id) => H.find((h) => h.id === id)).filter(Boolean).map((h) => h.title), value: null } : { ok: false, error: "not a how-to I have" };
}
export function say(res) {
  if (!res.ok) return { title: "How-to", body: res.error, result: res };
  const also = res.alt.length ? "\n\nRelated: " + res.alt.join("; ") + "." : "";
  return { title: res.title, body: (res.body ? res.body + "\n\n" : "") + "```" + res.lang + "\n" + res.code + "\n```" + also, note: (res.note ? res.note + " " : "") + "Curated snippet from DI's how-to library (hand-written and reviewed, not generated).", result: res };
}
